using System.Diagnostics;
using System.Text.Json.Nodes;
using Microsoft.Extensions.AI;

public class DotNetMcpClient : IAsyncDisposable
{
    private readonly Process _process;
    private readonly StreamWriter _stdin;
    private readonly StreamReader _stdout;
    private int _requestId = 0;

    public DotNetMcpClient(string command, string arguments)
    {
        var psi = new ProcessStartInfo
        {
            FileName = command,
            Arguments = arguments,
            RedirectStandardInput = true,
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        _process = Process.Start(psi) ?? throw new InvalidOperationException("Failed to launch MCP server.");
        _stdin = _process.StandardInput;
        _stdout = _process.StandardOutput;
    }

    public async Task InitializeAsync(CancellationToken ct = default)
    {
        var initRequest = new JsonObject
        {
            ["jsonrpc"] = "2.0",
            ["id"] = Interlocked.Increment(ref _requestId),
            ["method"] = "initialize",
            ["params"] = new JsonObject
            {
                ["protocolVersion"] = "2024-11-05",
                ["clientInfo"] = new JsonObject { ["name"] = "LearnAiHost", ["version"] = "1.0" }
            }
        };

        await _stdin.WriteLineAsync(initRequest.ToJsonString());
        await _stdout.ReadLineAsync(ct);
    }

    public async Task<List<AIFunction>> DiscoverToolsAsync(CancellationToken ct = default)
    {
        var listRequest = new JsonObject
        {
            ["jsonrpc"] = "2.0",
            ["id"] = Interlocked.Increment(ref _requestId),
            ["method"] = "tools/list"
        };

        await _stdin.WriteLineAsync(listRequest.ToJsonString());
        var responseLine = await _stdout.ReadLineAsync(ct);
        var node = JsonNode.Parse(responseLine!);
        var toolsArray = node?["result"]?["tools"]?.AsArray() ?? new JsonArray();

        var aiFunctions = new List<AIFunction>();
        foreach (var tool in toolsArray)
        {
            var toolName = tool!["name"]!.GetValue<string>();
            var desc = tool["description"]?.GetValue<string>() ?? string.Empty;

            // Wrap MCP tool as a callable AIFunction delegate
            aiFunctions.Add(AIFunctionFactory.Create(
                async (string inputJson) => await CallMcpToolAsync(toolName, inputJson, ct),
                name: toolName,
                description: desc));
        }

        return aiFunctions;
    }

    private async Task<string> CallMcpToolAsync(string name, string argsJson, CancellationToken ct)
    {
        var callRequest = new JsonObject
        {
            ["jsonrpc"] = "2.0",
            ["id"] = Interlocked.Increment(ref _requestId),
            ["method"] = "tools/call",
            ["params"] = new JsonObject
            {
                ["name"] = name,
                ["arguments"] = JsonNode.Parse(argsJson)
            }
        };

        await _stdin.WriteLineAsync(callRequest.ToJsonString());
        var responseLine = await _stdout.ReadLineAsync(ct);
        var resultNode = JsonNode.Parse(responseLine!);
        return resultNode?["result"]?["content"]?[0]?["text"]?.GetValue<string>() ?? "{}";
    }

    public async ValueTask DisposeAsync()
    {
        _process.Kill();
        await _process.WaitForExitAsync();
        _process.Dispose();
    }
}
